scripts.prebuild:
node -e "
const fs=require('fs');
let c=fs.readFileSync('educational-bot.jsx','utf8');
const MARKER='\n}\n\n        <div style={{marginBottom:22}}>';
if(c.includes(MARKER)){
  const i=c.indexOf(MARKER);
  const j=c.indexOf('\n// ============================================================\n// ADMIN LOGIN');
  c=c.slice(0,i+2)+c.slice(j);
  fs.writeFileSync('educational-bot.jsx',c);
  console.log('educational-bot.jsx: orphaned fragment removed');
} else { console.log('educational-bot.jsx: already clean'); }
"
